package com.interfacetransparency;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Settings are laid out the same way in every section:
 * the grouped toggle, the "All" slider, then the individual sliders in the order
 * they appear on screen. Config keys must never be renamed (that would reset
 * users' saved settings), only the display names and descriptions.
 */
@ConfigGroup("interfacetransparency")
public interface InterfaceTransparencyConfig extends Config
{
	// ---------------------------------------------------------------------
	// Resizable modern
	// ---------------------------------------------------------------------

	@ConfigSection(
		name = "Resizable modern",
		description = "Side panel in the resizable modern layout",
		position = 0
	)
	String modernSection = "modernSection";

	@ConfigItem(
		keyName = "modernGrouped",
		name = "Use one slider for all",
		description = "On: the 'All' slider controls this whole section. Off: the individual sliders are used.",
		section = modernSection,
		position = 0
	)
	default boolean modernGrouped()
	{
		return true;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "modernOpacity",
		name = "All (%)",
		description = "Everything in this section. Used when 'Use one slider for all' is on.",
		section = modernSection,
		position = 1
	)
	default int modernOpacity()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "modernBackground",
		name = "Tab stones (%)",
		description = "The stone behind each tab icon, including the active tab. Used when 'Use one slider for all' is off.",
		section = modernSection,
		position = 2
	)
	default int modernBackground()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "modernIcons",
		name = "Tab icons (%)",
		description = "The icon on each tab. Used when 'Use one slider for all' is off.",
		section = modernSection,
		position = 3
	)
	default int modernIcons()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "modernPanelBackground",
		name = "Panel background (%)",
		description = "The background of the side panel. Used when 'Use one slider for all' is off. "
			+ "0 = transparent, 100 = the game's look, whether or not 'Transparent side panel' is on.",
		section = modernSection,
		position = 4
	)
	default int modernPanelBackground()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "modernKeepPanelOpaque",
		name = "Keep panel background opaque",
		description = "At 100%, keeps the panel background solid even when the game's 'Transparent side panel' setting is on.",
		section = modernSection,
		position = 5
	)
	default boolean modernKeepPanelOpaque()
	{
		return false;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "modernBorder",
		name = "Panel border (%)",
		description = "The border around the side panel. Used when 'Use one slider for all' is off.",
		section = modernSection,
		position = 6
	)
	default int modernBorder()
	{
		return 100;
	}

	// ---------------------------------------------------------------------
	// Resizable classic
	// ---------------------------------------------------------------------

	@ConfigSection(
		name = "Resizable classic",
		description = "Side panel in the resizable classic layout",
		position = 1
	)
	String classicSection = "classicSection";

	@ConfigItem(
		keyName = "classicGrouped",
		name = "Use one slider for all",
		description = "On: the 'All' slider controls this whole section. Off: the individual sliders are used.",
		section = classicSection,
		position = 0
	)
	default boolean classicGrouped()
	{
		return true;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "classicOpacity",
		name = "All (%)",
		description = "Everything in this section. Used when 'Use one slider for all' is on.",
		section = classicSection,
		position = 1
	)
	default int classicOpacity()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "classicStones",
		name = "Tab stones (%)",
		description = "The stone behind each tab icon. Used when 'Use one slider for all' is off. "
			+ "Shares a few graphics with 'Tab icons'; the more transparent setting wins.",
		section = classicSection,
		position = 2
	)
	default int classicStones()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "classicIcons",
		name = "Tab icons (%)",
		description = "The icon on each tab. Used when 'Use one slider for all' is off. "
			+ "Shares a few graphics with 'Tab stones'; the more transparent setting wins.",
		section = classicSection,
		position = 3
	)
	default int classicIcons()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "classicPillars",
		name = "Pillars (%)",
		description = "The pillars at the sides of the panel. Used when 'Use one slider for all' is off.",
		section = classicSection,
		position = 4
	)
	default int classicPillars()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "classicBackground",
		name = "Panel background (%)",
		description = "The background of the side panel. Used when 'Use one slider for all' is off. "
			+ "0 = transparent, 100 = the game's look, whether or not 'Transparent side panel' is on.",
		section = classicSection,
		position = 5
	)
	default int classicBackground()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "classicKeepPanelOpaque",
		name = "Keep panel background opaque",
		description = "At 100%, keeps the panel background solid even when the game's 'Transparent side panel' setting is on.",
		section = classicSection,
		position = 6
	)
	default boolean classicKeepPanelOpaque()
	{
		return false;
	}

	// ---------------------------------------------------------------------
	// Chat
	// ---------------------------------------------------------------------

	@ConfigSection(
		name = "Chat",
		description = "Chat tabs, chat box and dialogs",
		position = 2
	)
	String chatSection = "chatSection";

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "chatButtons",
		name = "Tab buttons (%)",
		description = "The All, Game, Public, Private, Friends, Clan and Trade buttons and the report button.",
		section = chatSection,
		position = 0
	)
	default int chatButtons()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "chatBackground",
		name = "Tab background (%)",
		description = "The strip behind the chat tab buttons. "
			+ "0 = transparent, 100 = the game's look, whether or not 'Transparent chatbox' is on.",
		section = chatSection,
		position = 1
	)
	default int chatBackground()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "chatKeepBackgroundOpaque",
		name = "Keep tab background opaque",
		description = "At 100%, keeps the tab background solid even when the game's 'Transparent chatbox' setting is on.",
		section = chatSection,
		position = 2
	)
	default boolean chatKeepBackgroundOpaque()
	{
		return false;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "chatBoxBackground",
		name = "Chat box background (%)",
		description = "The background behind the chat messages. "
			+ "0 = transparent, 100 = the game's look, whether or not 'Transparent chatbox' is on.",
		section = chatSection,
		position = 3
	)
	default int chatBoxBackground()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "chatKeepBoxOpaque",
		name = "Keep chat box background opaque",
		description = "At 100%, keeps the chat box background solid even when the game's 'Transparent chatbox' setting is on.",
		section = chatSection,
		position = 4
	)
	default boolean chatKeepBoxOpaque()
	{
		return false;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "chatBorder",
		name = "Chat box border (%)",
		description = "The border around the chat box and the NPC, player and option dialogs, shown when 'Transparent chatbox' is off.",
		section = chatSection,
		position = 5
	)
	default int chatBorder()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "chatDialogBackground",
		name = "Dialog background (%)",
		description = "The background behind NPC and player dialogs and the option list. "
			+ "0 = transparent, 100 = the game's look.",
		section = chatSection,
		position = 6
	)
	default int chatDialogBackground()
	{
		return 100;
	}

	// ---------------------------------------------------------------------
	// Minimap
	// ---------------------------------------------------------------------

	@ConfigSection(
		name = "Minimap",
		description = "Minimap orbs and surround",
		position = 3
	)
	String minimapSection = "minimapSection";

	@ConfigItem(
		keyName = "minimapGrouped",
		name = "Use one slider for all",
		description = "On: the 'All' slider controls this whole section. Off: the individual sliders are used.",
		section = minimapSection,
		position = 0
	)
	default boolean minimapGrouped()
	{
		return true;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "minimapOpacity",
		name = "All (%)",
		description = "Everything in this section. Used when 'Use one slider for all' is on.",
		section = minimapSection,
		position = 1
	)
	default int minimapOpacity()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "minimapOrbs",
		name = "Orbs (%)",
		description = "The orbs: icons, fills and indicators. Used when 'Use one slider for all' is off.",
		section = minimapSection,
		position = 2
	)
	default int minimapOrbs()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "minimapOrbBoxes",
		name = "Orb backgrounds (%)",
		description = "The dark boxes and discs behind the orbs. Used when 'Use one slider for all' is off.",
		section = minimapSection,
		position = 3
	)
	default int minimapOrbBoxes()
	{
		return 100;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "minimapSurround",
		name = "Surround (%)",
		description = "The frame around the minimap. Used when 'Use one slider for all' is off.",
		section = minimapSection,
		position = 4
	)
	default int minimapSurround()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "showUpdateMessage",
		name = "Show update message",
		description = "Show a message in the chat box once on the first login after the plugin updates",
		position = 99
	)
	default boolean showUpdateMessage()
	{
		return true;
	}
}

package com.interfacetransparency;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID.ChatLeft;
import net.runelite.api.gameval.InterfaceID.Chatbox;
import net.runelite.api.gameval.InterfaceID.Chatmenu;
import net.runelite.api.gameval.InterfaceID.ChatRight;
import net.runelite.api.gameval.InterfaceID.Orbs;
import net.runelite.api.gameval.InterfaceID.ToplevelOsrsStretch;
import net.runelite.api.gameval.InterfaceID.ToplevelPreEoc;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Interface Transparency",
	description = "Change the opacity of the side panel tabs, the chat tabs and the minimap orbs and surround",
	tags = {"opacity", "transparent", "tabs", "stones", "chat", "interface"}
)
public class InterfaceTransparencyPlugin extends Plugin
{
	// ---- Resizable modern (ToplevelPreEoc, group 164) ----
	// There is no stone/icon 10 in this layout's widget tree.
	private static final int[] MODERN_STONES = {
		ToplevelPreEoc.STONE0, ToplevelPreEoc.STONE1, ToplevelPreEoc.STONE2,
		ToplevelPreEoc.STONE3, ToplevelPreEoc.STONE4, ToplevelPreEoc.STONE5,
		ToplevelPreEoc.STONE6, ToplevelPreEoc.STONE7, ToplevelPreEoc.STONE8,
		ToplevelPreEoc.STONE9, ToplevelPreEoc.STONE11, ToplevelPreEoc.STONE12,
		ToplevelPreEoc.STONE13
	};

	private static final int[] MODERN_ICONS = {
		ToplevelPreEoc.ICON0, ToplevelPreEoc.ICON1, ToplevelPreEoc.ICON2,
		ToplevelPreEoc.ICON3, ToplevelPreEoc.ICON4, ToplevelPreEoc.ICON5,
		ToplevelPreEoc.ICON6, ToplevelPreEoc.ICON7, ToplevelPreEoc.ICON8,
		ToplevelPreEoc.ICON9, ToplevelPreEoc.ICON11, ToplevelPreEoc.ICON12,
		ToplevelPreEoc.ICON13
	};

	private static final int[] MODERN_BACKGROUND = {
		ToplevelPreEoc.SIDE_STATIC_BACKGROUND,
		ToplevelPreEoc.SIDE_MOVABLE_BACKGROUND
	};

	// ---- Resizable classic (ToplevelOsrsStretch, group 161) ----
	// This layout has all 14 stones/icons (0-13).
	// TODO: SIDE_MENU_GRAPHIC0 and 4 (and any others) may exist; add them if parts of the panel don't fade.
	private static final int[] CLASSIC_STONES = {
		ToplevelOsrsStretch.STONE0, ToplevelOsrsStretch.STONE1, ToplevelOsrsStretch.STONE2,
		ToplevelOsrsStretch.STONE3, ToplevelOsrsStretch.STONE4, ToplevelOsrsStretch.STONE5,
		ToplevelOsrsStretch.STONE6, ToplevelOsrsStretch.STONE7, ToplevelOsrsStretch.STONE8,
		ToplevelOsrsStretch.STONE9, ToplevelOsrsStretch.STONE10, ToplevelOsrsStretch.STONE11,
		ToplevelOsrsStretch.STONE12, ToplevelOsrsStretch.STONE13
	};

	private static final int[] CLASSIC_ICONS = {
		ToplevelOsrsStretch.ICON0, ToplevelOsrsStretch.ICON1, ToplevelOsrsStretch.ICON2,
		ToplevelOsrsStretch.ICON3, ToplevelOsrsStretch.ICON4, ToplevelOsrsStretch.ICON5,
		ToplevelOsrsStretch.ICON6, ToplevelOsrsStretch.ICON7, ToplevelOsrsStretch.ICON8,
		ToplevelOsrsStretch.ICON9, ToplevelOsrsStretch.ICON10, ToplevelOsrsStretch.ICON11,
		ToplevelOsrsStretch.ICON12, ToplevelOsrsStretch.ICON13
	};

	// The side pillars (161.39 and 161.40)
	private static final int[] CLASSIC_PILLARS = {
		ToplevelOsrsStretch.SIDE_MENU_GRAPHIC1,
		ToplevelOsrsStretch.SIDE_MENU_GRAPHIC2
	};

	// Side graphics controlled by both the stones and the icons sliders (161.41 and 161.57).
	// A widget can only have one opacity, so the more transparent of the two settings is used.
	private static final int[] CLASSIC_SHARED = {
		ToplevelOsrsStretch.SIDE_MENU_GRAPHIC3,
		ToplevelOsrsStretch.SIDE_MENU_GRAPHIC5
	};

	// ---- Chat tabs (Chatbox, group 162), shared by every layout ----
	// These widgets have child widgets (button backgrounds, etc.), so they are
	// faded together with all of their children.
	private static final int[] CHAT_BUTTONS = {
		Chatbox.CHAT_ALL,
		Chatbox.CHAT_GAME,
		Chatbox.CHAT_PUBLIC,
		Chatbox.CHAT_PRIVATE,
		Chatbox.CHAT_FRIENDSCHAT,
		Chatbox.CHAT_CLAN,
		Chatbox.CHAT_TRADE,
		Chatbox.REPORTABUSE
	};

	// 162.2 and its children, except 162.3, which is handled on its own (see applyAbsolute)
	private static final int[] CHAT_BACKGROUND = {
		Chatbox.CONTROLS_BACKGROUND
	};

	// ---- Minimap ----
	// The orbs (Orbs, group 160) are shared by every layout. They have child widgets
	// (backing, icon, indicator and so on), so they are faded together with all of them.
	private static final int[] MINIMAP_ORBS = {
		Orbs.ORB_HEALTH,
		Orbs.ORB_PRAYER,
		Orbs.ORB_RUNENERGY,
		Orbs.ORB_SPECENERGY,
		Orbs.ORB_STORE,
		Orbs.ORB_WORLDMAP,
		Orbs.WIKI,
		Orbs.ORB_CONTENTRECOM,
		Orbs.XP_DROPS
	};

	// The boxes behind the orbs, including the dark "empty" disc each orb sits on.
	// These follow the Orb boxes slider and are faded linearly, not curved.
	private static final Set<Integer> ORB_BACKINGS = Set.of(
		Orbs.HEALTH_BACKING,
		Orbs.PRAYER_BACKING,
		Orbs.RUNENERGY_BACKING,
		Orbs.SPECENERGY_BACKING,
		Orbs.CR_BACKING,
		Orbs.WORLDMAP_BACKING,

		Orbs.ORB_HEALTH_EMPTY,
		Orbs.HEALTH_EMPTY_CONTENTS,
		Orbs.ORB_PRAYER_EMPTY,
		Orbs.ORB_PRAYER_EMPTY_GRAPHIC0,
		Orbs.ORB_RUNENERGY_EMPTY,
		Orbs.ORB_RUNENERGY_EMPTY_GRAPHIC0,
		Orbs.ORB_SPECENERGY_EMPTY,
		Orbs.ORB_SPECENERGY_EMPTY_GRAPHIC0
	);

	// The rest of each orb is several widgets stacked on top of each other, and each one is faded. Overlapping
	// layers keep the combined result looking opaque until each is quite transparent, so the orbs
	// slider is curved to compensate. Raise this if the orb icons still barely change at high values,
	// lower it (1 = no curve) if they change too fast.
	private static final int ORB_LAYERS = 2;

	// The minimap surround in the resizable modern layout.
	// Deliberately not included: ToplevelPreEoc.MINIMAP, which is the map itself.
	private static final int[] MINIMAP_SURROUND = {
		ToplevelPreEoc.MAP_NOCLICK_0, ToplevelPreEoc.MAP_NOCLICK_1, ToplevelPreEoc.MAP_NOCLICK_2,
		ToplevelPreEoc.MAP_NOCLICK_3, ToplevelPreEoc.MAP_NOCLICK_4, ToplevelPreEoc.MAP_NOCLICK_5,
		ToplevelPreEoc.MAP_MINIMAP_GRAPHIC6,
		ToplevelPreEoc.MAP_MINIMAP_GRAPHIC9
	};

	// The minimap surround in the resizable classic layout (161.32).
	private static final int[] MINIMAP_SURROUND_CLASSIC = {
		ToplevelOsrsStretch.MAP_MINIMAP_GRAPHIC9
	};

	// 0 means fully transparent. Raise this if you want a minimum visibility.
	private static final int MIN_PERCENT = 0;

	/**
	 * What we know about one widget we have changed.
	 * original: the opacity the game itself gave it (e.g. via the "Transparent side panel" or
	 *           "Transparent chatbox" settings).
	 * lastSet:  the last value this plugin wrote. If the widget's current opacity differs from
	 *           it, the game changed it, and the current value becomes the new original.
	 */
	private static class State
	{
		Widget widget;
		int original;
		int lastSet;
		boolean modified;
	}

	// ---- "What's new" message ----
	// Shown once in the chat box on the first login after the plugin updates.
	// When you release something players should hear about, bump VERSION and edit WHATS_NEW.
	private static final String CONFIG_GROUP = "interfacetransparency";
	private static final String VERSION_KEY = "lastSeenVersion";
	private static final String VERSION = "3";
	private static final String WHATS_NEW =
		"Interface Transparency: new chat box, dialog and side panel background sliders, and the chat settings are simpler. Open the plugin settings to try them.";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private InterfaceTransparencyConfig config;

	private final Map<Long, State> states = new HashMap<>();

	private boolean updateMessagePending;

	@Provides
	InterfaceTransparencyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(InterfaceTransparencyConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateChatSettings();

		// If the plugin is switched on while already logged in, greet straight away
		updateMessagePending = client.getGameState() == GameState.LOGGED_IN && needsUpdateMessage();
	}

	/**
	 * The chat section used to have a "Use one slider for all" toggle and an "All" slider. Both were removed.
	 * Anyone who was using the shared slider gets its value copied to the individual sliders, so their chat
	 * looks the same as before.
	 */
	private void migrateChatSettings()
	{
		String all = configManager.getConfiguration(CONFIG_GROUP, "chatOpacity");
		if (all == null)
		{
			return;
		}

		String grouped = configManager.getConfiguration(CONFIG_GROUP, "chatGrouped");
		if (!"false".equals(grouped))
		{
			for (String key : new String[]{"chatButtons", "chatBackground", "chatBoxBackground", "chatBorder"})
			{
				configManager.setConfiguration(CONFIG_GROUP, key, all);
			}
		}

		configManager.unsetConfiguration(CONFIG_GROUP, "chatOpacity");
		configManager.unsetConfiguration(CONFIG_GROUP, "chatGrouped");
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(this::restoreAll);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN && needsUpdateMessage())
		{
			updateMessagePending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Wait a tick after login so the chat box is ready
		if (!updateMessagePending || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		updateMessagePending = false;
		client.addChatMessage(
			ChatMessageType.GAMEMESSAGE,
			"",
			new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append(WHATS_NEW).build(),
			null);
		configManager.setConfiguration(CONFIG_GROUP, VERSION_KEY, VERSION);
	}

	private boolean needsUpdateMessage()
	{
		return config.showUpdateMessage()
			&& !VERSION.equals(configManager.getConfiguration(CONFIG_GROUP, VERSION_KEY));
	}

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		applyAll();
	}

	/**
	 * Applies every setting. Called on each client tick and again just before each frame is drawn
	 * (see onBeforeRender).
	 */
	private void applyAll()
	{
		applySidePanel();
		applyChat();
		applyMinimap();
	}

	private void applyMinimap()
	{
		boolean minimap = config.minimapGrouped();
		applyOrbs(
			minimap ? config.minimapOpacity() : config.minimapOrbs(),
			minimap ? config.minimapOpacity() : config.minimapOrbBoxes());
		int surround = minimap ? config.minimapOpacity() : config.minimapSurround();
		apply(MINIMAP_SURROUND, surround, false);
		apply(MINIMAP_SURROUND_CLASSIC, surround, false);
	}

	/**
	 * Runs just before each frame is drawn. The game can reset the side panel, chat and minimap widgets (for
	 * example when a tab is switched, an item moves or the chat box opens or closes), so they are
	 * applied again here to avoid a flash back to the default look.
	 */
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		applyAll();
	}

	private void applySidePanel()
	{
		// Only the active layout's widgets exist, so applying both is harmless:
		// the other layout's lookups just return null.
		boolean modern = config.modernGrouped();
		// The stones slider covers both the stone background and the highlighted active tab
		int modernStones = modern ? config.modernOpacity() : config.modernBackground();
		apply(MODERN_STONES, modernStones, false);
		apply(MODERN_ICONS, modern ? config.modernOpacity() : config.modernIcons(), false);
		apply(MODERN_BACKGROUND, modernStones, false);
		applyAbsolute(ToplevelPreEoc.SIDE_BACKGROUND, modern ? config.modernOpacity() : config.modernPanelBackground(),
			config.modernKeepPanelOpaque());
		applyDynamicChildren(ToplevelPreEoc.SIDE_CONTAINER, modern ? config.modernOpacity() : config.modernBorder());

		boolean classic = config.classicGrouped();
		apply(CLASSIC_STONES, classic ? config.classicOpacity() : config.classicStones(), false);
		apply(CLASSIC_ICONS, classic ? config.classicOpacity() : config.classicIcons(), false);
		apply(CLASSIC_SHARED, classic ? config.classicOpacity() : Math.min(config.classicStones(), config.classicIcons()), false);
		apply(CLASSIC_PILLARS, classic ? config.classicOpacity() : config.classicPillars(), false);
		// The panel backgrounds follow the slider directly (0% = transparent, 100% = the game's own
		// look), so they can be controlled whatever the game's "Transparent side panel" setting is.
		applyAbsolute(ToplevelOsrsStretch.SIDE_BACKGROUND, classic ? config.classicOpacity() : config.classicBackground(),
			config.classicKeepPanelOpaque());
	}

	/**
	 * True while a dialog or other popup is showing in the chat box: the NPC dialog, the player dialog,
	 * the option list, or anything else loaded into the chat modal area (message boxes and so on).
	 */
	private boolean isChatPopupOpen()
	{
		if (isVisible(client.getWidget(ChatLeft.UNIVERSE))
			|| isVisible(client.getWidget(ChatRight.UNIVERSE))
			|| isVisible(client.getWidget(Chatmenu.UNIVERSE)))
		{
			return true;
		}

		Widget modal = client.getWidget(Chatbox.CHATMODAL);
		if (modal == null || modal.isHidden())
		{
			return false;
		}

		Widget[] nested = modal.getNestedChildren();
		return nested != null && nested.length > 0;
	}

	private static boolean isVisible(Widget w)
	{
		return w != null && !w.isHidden();
	}

	private void applyChat()
	{
		apply(CHAT_BUTTONS, config.chatButtons(), true);
		apply(CHAT_BACKGROUND, config.chatBackground(), true);
		applyAbsolute(Chatbox.CONTROLS_BACKGROUND_GRAPHIC, config.chatBackground(),
			config.chatKeepBackgroundOpaque());
		// The border around the chat box and dialogs (162.34), also made of dynamic children
		applyAbsoluteToChildren(Chatbox.CHATAREA, config.chatBorder(), false);

		// The chat box area (162.37), which is made of dynamic children. The same widgets draw the
		// parchment behind dialogs and popups, so while one is open they follow the dialog slider instead.
		if (isChatPopupOpen())
		{
			applyAbsoluteToChildren(Chatbox.CHAT_BACKGROUND, config.chatDialogBackground(), false);
		}
		else
		{
			applyAbsoluteToChildren(Chatbox.CHAT_BACKGROUND, config.chatBoxBackground(),
				config.chatKeepBoxOpaque());
		}
	}

	/**
	 * Converts the slider value into the per-layer opacity that gives the same overall look when
	 * ORB_LAYERS layers are stacked. 100 stays 100 so the game's own appearance is untouched.
	 */
	private static int layered(int percent)
	{
		if (percent >= 100)
		{
			return 100;
		}

		double visible = Math.max(0, percent) / 100.0;
		return (int) Math.round(100 * (1 - Math.pow(1 - visible, 1.0 / ORB_LAYERS)));
	}

	/**
	 * Fades every orb and all of its children. The backing boxes use their own slider value as it
	 * is; everything else uses the orbs slider with the layered curve.
	 */
	private void applyOrbs(int orbPercent, int boxPercent)
	{
		for (int id : MINIMAP_ORBS)
		{
			applyOrbTree(client.getWidget(id), orbPercent, boxPercent);
		}
	}

	private void applyOrbTree(Widget w, int orbPercent, int boxPercent)
	{
		if (w == null)
		{
			return;
		}

		int p = ORB_BACKINGS.contains(w.getId()) ? boxPercent : layered(orbPercent);
		applyWidget(w, p, Math.max(MIN_PERCENT, Math.min(100, p)));
		applyOrbChildren(w.getStaticChildren(), orbPercent, boxPercent);
		applyOrbChildren(w.getDynamicChildren(), orbPercent, boxPercent);
		applyOrbChildren(w.getNestedChildren(), orbPercent, boxPercent);
	}

	private void applyOrbChildren(Widget[] widgets, int orbPercent, int boxPercent)
	{
		if (widgets == null)
		{
			return;
		}

		for (Widget child : widgets)
		{
			applyOrbTree(child, orbPercent, boxPercent);
		}
	}

	private void apply(int[] ids, int percent, boolean includeChildren)
	{
		int clamped = Math.max(MIN_PERCENT, Math.min(100, percent));

		for (int id : ids)
		{
			Widget w = client.getWidget(id);
			if (includeChildren)
			{
				applyTree(w, percent, clamped);
			}
			else if (w != null)
			{
				applyWidget(w, percent, clamped);
			}
		}
	}

	/**
	 * Fades only the dynamic children of a container (for example the side panel border pieces),
	 * leaving the container itself and its other contents alone.
	 */
	private void applyDynamicChildren(int id, int percent)
	{
		Widget container = client.getWidget(id);
		if (container == null)
		{
			return;
		}

		Widget[] children = container.getDynamicChildren();
		if (children == null)
		{
			return;
		}

		int clamped = Math.max(MIN_PERCENT, Math.min(100, percent));
		for (Widget child : children)
		{
			if (child != null)
			{
				applyWidget(child, percent, clamped);
			}
		}
	}

	private void applyTree(Widget w, int percent, int clamped)
	{
		if (w == null)
		{
			return;
		}

		if (w.getId() == Chatbox.CONTROLS_BACKGROUND_GRAPHIC)
		{
			return; // handled by applyAbsolute
		}

		applyWidget(w, percent, clamped);
		applyAll(w.getStaticChildren(), percent, clamped);
		applyAll(w.getDynamicChildren(), percent, clamped);
		applyAll(w.getNestedChildren(), percent, clamped);
	}

	private void applyAll(Widget[] widgets, int percent, int clamped)
	{
		if (widgets == null)
		{
			return;
		}

		for (Widget child : widgets)
		{
			applyTree(child, percent, clamped);
		}
	}

	/**
	 * Scales one widget's visibility by the slider percent, relative to whatever opacity the
	 * game itself gave it (RuneLite opacity: 0 = opaque, 255 = invisible). At 100% the widget
	 * is left at the game's value, so the in-game transparency settings keep working.
	 */
	private void applyWidget(Widget w, int percent, int clamped)
	{
		// Dynamic children share their parent's id and are told apart by index
		long key = ((long) w.getId() << 16) | (w.getIndex() + 1);

		State s = states.get(key);
		if (s == null)
		{
			if (percent >= 100)
			{
				return; // never touched this one, nothing to undo
			}
			s = new State();
			states.put(key, s);
		}

		s.widget = w;
		int current = w.getOpacity();
		if (!s.modified || current != s.lastSet)
		{
			// Not a value we wrote, so the game set it. Treat it as the new baseline.
			s.original = current;
		}

		int target = percent >= 100 ? s.original : 255 - ((255 - s.original) * clamped / 100);
		if (current != target)
		{
			w.setOpacity(target);
		}

		if (percent >= 100)
		{
			states.remove(key);
		}
		else
		{
			s.lastSet = target;
			s.modified = true;
		}
	}

	/**
	 * Sets a widget's opacity straight from the slider, ignoring the opacity the game gave it:
	 * 0% = fully transparent (255), 100% = fully opaque (0). At 100% the plugin stops touching the
	 * widget and puts the game's own value back, so by default nothing changes. With opaqueAt100 on,
	 * 100% instead keeps the widget fully opaque, whatever the game's own transparency setting is.
	 */
	private void applyAbsolute(int id, int percent, boolean opaqueAt100)
	{
		applyAbsolute(client.getWidget(id), percent, opaqueAt100);
	}

	/**
	 * Same as applyAbsolute(int, ...), for the dynamic children of a widget (each one is a separate
	 * piece of the drawing). The parent itself is left alone.
	 */
	private void applyAbsoluteToChildren(int id, int percent, boolean opaqueAt100)
	{
		Widget parent = client.getWidget(id);
		Widget[] children = parent == null ? null : parent.getDynamicChildren();
		if (children == null)
		{
			return;
		}

		for (Widget child : children)
		{
			applyAbsolute(child, percent, opaqueAt100);
		}
	}

	private void applyAbsolute(Widget w, int percent, boolean opaqueAt100)
	{
		if (w == null)
		{
			return;
		}

		long key = ((long) w.getId() << 16) | (w.getIndex() + 1);
		State s = states.get(key);

		if (percent >= 100 && !opaqueAt100)
		{
			if (s != null)
			{
				if (s.modified && w.getOpacity() == s.lastSet)
				{
					w.setOpacity(s.original);
				}
				states.remove(key);
			}
			return;
		}

		if (s == null)
		{
			s = new State();
			states.put(key, s);
		}

		s.widget = w;
		int current = w.getOpacity();
		if (!s.modified || current != s.lastSet)
		{
			s.original = current;
		}

		int clamped = Math.max(MIN_PERCENT, Math.min(100, percent));
		int target = 255 - (255 * clamped / 100);
		if (current != target)
		{
			w.setOpacity(target);
		}

		s.lastSet = target;
		s.modified = true;
	}

	/**
	 * Puts back the game's own opacity for every widget this plugin changed. The widget is looked
	 * up again by its id, because the game (or another plugin) may have rebuilt it since we last
	 * touched it, which would leave the widget we stored detached from what is on screen.
	 */
	private void restoreAll()
	{
		for (Map.Entry<Long, State> entry : states.entrySet())
		{
			State s = entry.getValue();
			if (!s.modified)
			{
				continue;
			}

			restoreWidget(findWidget(entry.getKey()), s);
			if (s.widget != null)
			{
				restoreWidget(s.widget, s);
			}
		}
		states.clear();
	}

	private static void restoreWidget(Widget w, State s)
	{
		if (w != null && w.getOpacity() == s.lastSet)
		{
			w.setOpacity(s.original);
		}
	}

	/**
	 * Finds the widget a state key was made from (see applyWidget): the id is in the upper bits
	 * and the index (+1) in the lower 16. Dynamic children share their parent's id.
	 */
	private Widget findWidget(long key)
	{
		Widget w = client.getWidget((int) (key >>> 16));
		int index = (int) (key & 0xFFFF) - 1;
		return w == null || index < 0 ? w : w.getChild(index);
	}
}

